.check => {
    // Load imports only for MO0501's type information. Loader/checker findings
    // stay out of fmt. If loading stops in a dependency, keep the formatter's
    // existing best-effort loop check over the already-parsed requested source.
    var load_diags: mo.diag.List = .empty;
    const loaded = try mo.program.loadSource(arena, io, path, source, &load_diags);
    const loop_program = if (std.mem.eql(u8, loaded.main().path, path))
        loaded
    else
        try mo.program.single(arena, path, source);
    var findings: mo.diag.List = .empty;
    try mo.pipeline.loopFindings(arena, loop_program, &findings);
    const changed = !std.mem.eql(u8, source, formatted);
    if (changed) try mo.diff.unified(arena, out, path, source, formatted);
    if (changed or findings.items.len > 0) return reject(out, err, loop_program.files, findings.items, json);
},

reviewed_current_sections.corpus_helper:
pub fn fmtCheck(gpa: std.mem.Allocator, io: Io, root: []const u8, rel: []const u8) !bool {
    var dir = try Io.Dir.cwd().openDir(io, root, .{});
    defer dir.close(io);
    var arena_state = std.heap.ArenaAllocator.init(gpa);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    const source = try dir.readFileAlloc(io, rel, arena, .limited(1 << 20));
    // A rejects file that expects a syntax code does not parse, so it has no one shape.
    if (isRejectsPath(rel)) if (expectedCode(source)) |code| if (std.mem.startsWith(u8, code, "MO01")) return true;
    var diags: diag.List = .empty;
    const formatted = fmt.format(arena, source, &diags) catch |err| switch (err) {
        error.Rejected => {
            std.debug.print("corpus: {s} does not format: {s} {s}\n", .{ rel, diags.items[0].code, diags.items[0].what });
            return false;
        },
        else => return err,
    };
    if (!std.mem.eql(u8, source, formatted)) {
        std.debug.print("corpus: {s} is not formatted; run mo fmt on it\n", .{rel});
        return false;
    }
    const path = try std.fs.path.join(arena, &.{ root, rel });
    var load_diags: diag.List = .empty;
    const loaded = try program.loadSource(arena, io, path, source, &load_diags);
    const loop_program = if (std.mem.eql(u8, loaded.main().path, path))
        loaded
    else
        try program.single(arena, path, source);
    var findings: diag.List = .empty;
    pipeline.loopFindings(arena, loop_program, &findings) catch |err| switch (err) {
        error.Rejected => {},
        else => return err,
    };
    if (findings.items.len > 0) {
        const loc = diag.locate(loop_program.files, findings.items[0].at);
        std.debug.print("corpus: {s} at byte {d}: {s} {s}\n", .{ rel, loc.at, findings.items[0].code, findings.items[0].what });
        return false;
    }
    return true;
}

reviewed_current_sections.regression:
test "corpus: fmt check classifies imported calls and keeps dependency findings out of the requested file" {
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    var arena_state = std.heap.ArenaAllocator.init(gpa);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    const from_environ = std.testing.environ.getAlloc(gpa, "MO_EXE") catch null;
    defer if (from_environ) |e| gpa.free(e);
    const mo_exe = try moExe(gpa, io, from_environ);
    defer gpa.free(mo_exe);
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDirPath(io, "app/lib");
    try tmp.dir.writeFile(io, .{ .sub_path = "app/mo.root", .data = "" });
    const tally =
        \\module Lib.Tally
        \\expose Tally
        \\
        \\intent "Count votes."
        \\
        \\process Tally()
        \\  state
        \\    votes: UInt32
        \\  end
        \\
        \\  message Vote
        \\  message Total : UInt32
        \\
        \\  fn update(state, message)
        \\    case message
        \\      Vote:
        \\        state.votes += 1
        \\      Total: state.votes
        \\    end
        \\  end
        \\end
        \\
    ;
    const effect_main =
        \\module EffectMain
        \\
        \\use Lib.Tally{Tally}
        \\
        \\intent "Use an imported process handle."
        \\
        \\test "ask and send through an imported handle are effects"
        \\  tally = Tally.start()
        \\  for _ in 0..2
        \\    tally.send(Vote)
        \\    assert tally.ask(Total, within: 1.seconds) is Ok(_)
        \\  end
        \\end
        \\
    ;
    const double =
        \\module Lib.Double
        \\expose double
        \\
        \\intent "Double a number."
        \\
        \\fn double(n: UInt32) : UInt32
        \\  n * 2
        \\end
        \\
    ;
    const pure_main =
        \\module PureMain
        \\
        \\use Lib.Double{double}
        \\
        \\intent "Call an imported pure function."
        \\
        \\test "an imported pure call leaves the loop pure"
        \\  for n in [1, 2]
        \\    assert double(n) > 0
        \\  end
        \\end
        \\
    ;
    const loopy =
        \\module Lib.Loopy
        \\expose one
        \\
        \\intent "Hold a pure loop in a dependency."
        \\
        \\fn one() : UInt32
        \\  1
        \\end
        \\
        \\test "the dependency itself has a pure loop"
        \\  for n in [1, 2]
        \\    assert n >= one()
        \\  end
        \\end
        \\
    ;
    const clean_main =
        \\module CleanMain
        \\
        \\use Lib.Loopy{one}
        \\
        \\intent "Call a dependency without copying its loop finding."
        \\
        \\test "the requested module has no loop"
        \\  assert one() == 1
        \\end
        \\
    ;
    const broken =
        \\module Lib.Broken
        \\
        \\fn broken(
        \\
    ;
    const stopped_pure =
        \\module StoppedPure
        \\
        \\use Lib.Broken{broken}
        \\
        \\intent "Keep checking a requested pure loop after dependency loading stops."
        \\
        \\test "the requested pure loop is still checked"
        \\  for n in [1, 2]
        \\    assert n > 0
        \\  end
        \\end
        \\
    ;
    const stopped_clean =
        \\module StoppedClean
        \\
        \\use Lib.Broken{broken}
        \\
        \\intent "Keep a clean requested file clean after dependency loading stops."
        \\
        \\test "the requested file has no loop"
        \\  assert true
        \\end
        \\
    ;
    try tmp.dir.writeFile(io, .{ .sub_path = "app/lib/tally.mo", .data = tally });
    try tmp.dir.writeFile(io, .{ .sub_path = "app/effect-main.mo", .data = effect_main });
    try tmp.dir.writeFile(io, .{ .sub_path = "app/lib/double.mo", .data = double });
    try tmp.dir.writeFile(io, .{ .sub_path = "app/pure-main.mo", .data = pure_main });
    try tmp.dir.writeFile(io, .{ .sub_path = "app/lib/loopy.mo", .data = loopy });
    try tmp.dir.writeFile(io, .{ .sub_path = "app/clean-main.mo", .data = clean_main });
    try tmp.dir.writeFile(io, .{ .sub_path = "app/lib/broken.mo", .data = broken });
    try tmp.dir.writeFile(io, .{ .sub_path = "app/stopped-pure.mo", .data = stopped_pure });
    try tmp.dir.writeFile(io, .{ .sub_path = "app/stopped-clean.mo", .data = stopped_clean });
    const root = try std.fmt.allocPrint(arena, ".zig-cache/tmp/{s}/app", .{tmp.sub_path});

    const effect_cli = try std.process.run(arena, io, .{ .argv = &.{ mo_exe, "fmt", "--check", "effect-main.mo" }, .cwd = .{ .path = root } });
    try std.testing.expect(effect_cli.term == .exited and effect_cli.term.exited == 0);
    try std.testing.expect(try fmtCheck(gpa, io, root, "effect-main.mo"));

    const pure_cli = try std.process.run(arena, io, .{ .argv = &.{ mo_exe, "fmt", "--check", "pure-main.mo" }, .cwd = .{ .path = root } });
    try std.testing.expect(pure_cli.term == .exited and pure_cli.term.exited == 1);
    try std.testing.expect(std.mem.indexOf(u8, pure_cli.stderr, "pure-main.mo:8:3: MO0501") != null);
    try std.testing.expect(!try fmtCheck(gpa, io, root, "pure-main.mo"));

    const clean_cli = try std.process.run(arena, io, .{ .argv = &.{ mo_exe, "fmt", "--check", "clean-main.mo" }, .cwd = .{ .path = root } });
    try std.testing.expect(clean_cli.term == .exited and clean_cli.term.exited == 0);
    try std.testing.expect(try fmtCheck(gpa, io, root, "clean-main.mo"));

    const stopped_pure_cli = try std.process.run(arena, io, .{ .argv = &.{ mo_exe, "fmt", "--check", "stopped-pure.mo" }, .cwd = .{ .path = root } });
    try std.testing.expect(stopped_pure_cli.term == .exited and stopped_pure_cli.term.exited == 1);
    try std.testing.expect(std.mem.indexOf(u8, stopped_pure_cli.stderr, "stopped-pure.mo:8:3: MO0501") != null);
    try std.testing.expect(!try fmtCheck(gpa, io, root, "stopped-pure.mo"));

    const stopped_clean_cli = try std.process.run(arena, io, .{ .argv = &.{ mo_exe, "fmt", "--check", "stopped-clean.mo" }, .cwd = .{ .path = root } });
    try std.testing.expect(stopped_clean_cli.term == .exited and stopped_clean_cli.term.exited == 0);
    try std.testing.expect(try fmtCheck(gpa, io, root, "stopped-clean.mo"));
}
